<script setup>
import {computed} from 'vue';
import {X,ArrowUpRight,Focus} from 'lucide-vue-next';
const props=defineProps({poi:Object});const emit=defineEmits(['close','focus']);
const status=computed(()=>({normal:'运行正常',warning:'需要关注',offline:'离线'}[props.poi.status]||'运行正常'));
const link=computed(()=>/^https?:\/\//i.test(props.poi.link||'')?props.poi.link:'');
</script>
<template><section class="aw-poi-card ase-info-card" :class="['info-'+(poi.style||'glass'),'status-'+(poi.status||'normal')]" :style="{'--poi-color':poi.color||'#9ccdeb'}" role="dialog" :aria-label="poi.name+'详情'" @pointerdown.stop @click.stop>
 <header><span>SPATIAL INSIGHT <i>空间信息</i></span><button aria-label="关闭空间信息" @click="emit('close')"><X :size="15"/></button></header>
 <div class="ase-info-title"><i></i><h3>{{poi.name}}</h3><span>{{status}}</span></div>
 <p v-if="poi.description" class="ase-info-description">{{poi.description}}</p>
 <dl v-if="poi.rows?.length"><div v-for="(row,i) in poi.rows" :key="i"><dt>{{row.label}}</dt><dd>{{row.value}}<small v-if="row.unit">{{row.unit}}</small></dd></div></dl>
 <div v-else class="ase-info-metric"><strong>{{Number.isFinite(Number(poi.value))?Number(poi.value).toFixed(1):poi.value||'—'}}</strong><small>{{poi.unit}}</small></div>
 <footer><button @click="emit('focus')"><Focus :size="13"/>聚焦此位置</button><a v-if="link" :href="link" target="_blank" rel="noopener noreferrer">{{poi.linkText||'查看详情'}}<ArrowUpRight :size="13"/></a><span v-else>{{poi.objectId?'场景信息 · 自定义':'模板演示数据'}}</span></footer>
</section></template>
<style>
.aw-poi-card.ase-info-card{position:absolute;z-index:8;top:104px;right:22px;width:min(330px,calc(100% - 32px));padding:0;border:1px solid color-mix(in srgb,var(--poi-color) 24%,transparent);border-radius:13px;background:linear-gradient(145deg,#172536f2,#0c1725f7);color:#dce8f2;box-shadow:0 20px 70px #0006,inset 0 1px #fff1;backdrop-filter:blur(22px);font-family:Inter,'PingFang SC',sans-serif;max-height:calc(100% - 120px);overflow:auto;scrollbar-width:thin;scrollbar-color:#587388 transparent;pointer-events:auto}.aw-poi-card.ase-info-card.info-solid{background:#132232;backdrop-filter:none}.ase-info-card>header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d7e9ff0d;padding:13px 16px}.ase-info-card>header>span{font-size:9px;letter-spacing:1.4px;color:var(--poi-color)}.ase-info-card>header i{font-style:normal;letter-spacing:0;color:#7b93a9;margin-left:8px}.ase-info-card button{display:inline-flex;align-items:center;gap:6px;background:none;border:0;color:#b3c8d8;font-family:inherit;font-size:11px;cursor:pointer;padding:4px}.ase-info-card button:hover,.ase-info-card a:hover{color:var(--poi-color)}.ase-info-title{display:flex;align-items:center;gap:7px;padding:16px 16px 6px!important;border:0!important}.ase-info-title>i{width:5px;height:5px;background:#71d2b0;border-radius:50%}.status-warning .ase-info-title>i{background:#e6b56a}.status-offline .ase-info-title>i{background:#8396a9}.ase-info-title h3{font-size:16px!important;font-weight:550;line-height:1.5;flex:1;margin:0!important;color:#e9f1f8;overflow-wrap:anywhere}.ase-info-title>span{font-size:9px;color:#91a9b8;white-space:nowrap}.ase-info-description{font-size:11px;line-height:1.8;color:#8da4b8;margin:0;padding:3px 16px 12px;white-space:pre-wrap;overflow-wrap:anywhere}.ase-info-card dl{margin:0;padding:0 16px 8px}.ase-info-card dl>div{display:flex;align-items:baseline;gap:18px;justify-content:space-between;padding:11px 0;border-bottom:1px solid #b9d3e40c}.ase-info-card dt{color:#879fb3;font-size:11px}.ase-info-card dd{margin:0;font-size:15px;color:#dae8f4;font-variant-numeric:tabular-nums;overflow-wrap:anywhere;text-align:right}.ase-info-card dd small{font-size:10px;color:#88a3b9;margin-left:5px}.ase-info-card footer{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-top:1px solid #bddcff0c}.ase-info-card footer>span{font-size:9px;letter-spacing:.5px;color:#5f7c91}.ase-info-card a{display:flex;align-items:center;gap:3px;font-size:11px;color:var(--poi-color);text-decoration:none}.ase-info-metric{padding:10px 18px 20px!important;display:flex;align-items:baseline;gap:8px}.ase-info-metric strong{font-size:32px!important;color:var(--poi-color);font-weight:500}.ase-info-metric small{font-size:11px;color:#7f9aae}@media(max-width:600px){.aw-poi-card.ase-info-card{top:68px;right:12px;width:min(280px,calc(100% - 24px))}}
</style>
